TEMPLATES = {
    'base.html': '<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>{% block title %}QuestLog{% endblock %}</title>\n  <link rel="stylesheet" href="{{ url_for(\'static\', filename=\'style.css\') }}">\n</head>\n<body>\n  <nav class="nav">\n    <a class="brand" href="{{ url_for(\'index\') }}">⚔️ QuestLog</a>\n    {% if current_user %}\n    <div class="nav-right">\n      <span class="nav-user">{{ current_user[\'username\'] }}</span>\n      <form method="post" action="{{ url_for(\'logout\') }}" class="inline">\n        <input type="hidden" name="csrf" value="{{ csrf }}">\n        <button class="btn btn-ghost" type="submit">Log out</button>\n      </form>\n    </div>\n    {% else %}\n    <div class="nav-right">\n      <a class="btn btn-ghost" href="{{ url_for(\'login\') }}">Log in</a>\n      <a class="btn btn-primary" href="{{ url_for(\'register\') }}">Sign up</a>\n    </div>\n    {% endif %}\n  </nav>\n  <main class="container">\n    {% with messages = get_flashed_messages(with_categories=true) %}\n      {% if messages %}\n      <div class="flashes">\n        {% for category, message in messages %}\n        <div class="flash flash-{{ category }}">{{ message }}</div>\n        {% endfor %}\n      </div>\n      {% endif %}\n    {% endwith %}\n    {% block content %}{% endblock %}\n  </main>\n</body>\n</html>\n',
    'index.html': '{% extends "base.html" %}\n{% block content %}\n<section class="stats">\n  <div class="card stat">\n    <div class="stat-label">Points</div>\n    <div class="stat-value">{{ current_user[\'points\'] }}</div>\n  </div>\n  <div class="card stat">\n    <div class="stat-label">Level {{ level }}</div>\n    <div class="progress"><div class="progress-fill" style="width: {{ progress }}%"></div></div>\n    <div class="stat-sub">{{ current_user[\'points\'] - lo }} / {{ hi - lo }} pts to level {{ level + 1 }}</div>\n  </div>\n  <div class="card stat">\n    <div class="stat-label">Streak</div>\n    <div class="stat-value">🔥 {{ current_user[\'streak\'] }}</div>\n  </div>\n  <div class="card stat">\n    <div class="stat-label">Quests done</div>\n    <div class="stat-value">{{ current_user[\'tasks_done\'] }}</div>\n    <div class="stat-sub">{{ on_time_rate }}% on time</div>\n  </div>\n</section>\n\n<section class="card">\n  <h2>New quest</h2>\n  <form method="post" action="{{ url_for(\'add_task\') }}" class="task-form">\n    <input type="hidden" name="csrf" value="{{ csrf }}">\n    <input type="text" name="title" maxlength="120" placeholder="Quest title" required>\n    <input type="datetime-local" name="due" required>\n    <select name="difficulty">\n      {% for key, label in difficulties.items() %}\n      <option value="{{ key }}" {% if key == \'normal\' %}selected{% endif %}>{{ label }}</option>\n      {% endfor %}\n    </select>\n    <textarea name="description" placeholder="Description (optional)" rows="2"></textarea>\n    <button class="btn btn-primary" type="submit">Add quest</button>\n  </form>\n  <p class="hint">\n    Finish before the deadline: full base points + {{ (on_time_bonus * 100)|int }}% bonus.\n    Finish late: ×{{ late_penalty }}. Each postpone (+1 day): −{{ decay_pct }}% of base points.\n    Daily streak adds up to +{{ streak_cap }} pts per completion.\n  </p>\n</section>\n\n<section>\n  <h2>Open quests</h2>\n  {% if tasks %}\n  <div class="task-list">\n    {% for t in tasks %}\n    <div class="card task {% if t.overdue %}overdue{% endif %}">\n      <div class="task-main">\n        <div class="task-title">{{ t.title }}</div>\n        {% if t.description %}<div class="task-desc">{{ t.description }}</div>{% endif %}\n        <div class="task-meta">\n          <span class="tag tag-{{ t.difficulty }}">{{ t.difficulty }}</span>\n          <span>Due {{ t.due_at|localdt }}{% if t.overdue %} · <strong>overdue</strong>{% endif %}</span>\n          {% if t.postpones %}<span class="tag tag-postpone">postponed ×{{ t.postpones }}</span>{% endif %}\n          <span class="tag tag-points">worth {{ t.worth_now }} pts if done now</span>\n        </div>\n      </div>\n      <div class="task-actions">\n        <form method="post" action="{{ url_for(\'complete_task\', task_id=t.id) }}">\n          <input type="hidden" name="csrf" value="{{ csrf }}">\n          <button class="btn btn-primary" type="submit">Done</button>\n        </form>\n        <form method="post" action="{{ url_for(\'postpone_task\', task_id=t.id) }}">\n          <input type="hidden" name="csrf" value="{{ csrf }}">\n          <button class="btn btn-warn" type="submit">+1 day</button>\n        </form>\n        <form method="post" action="{{ url_for(\'delete_task\', task_id=t.id) }}">\n          <input type="hidden" name="csrf" value="{{ csrf }}">\n          <button class="btn btn-ghost" type="submit" title="Delete">✕</button>\n        </form>\n      </div>\n    </div>\n    {% endfor %}\n  </div>\n  {% else %}\n  <p class="empty">No open quests. Add one above — your future self will thank you.</p>\n  {% endif %}\n</section>\n\n{% if badges %}\n<section>\n  <h2>Badges</h2>\n  <div class="badge-list">\n    {% for b in badges %}\n    <div class="badge" title="{{ badges_def[b.badge][1] if b.badge in badges_def else \'\' }}">\n      🏅 {{ badges_def[b.badge][0] if b.badge in badges_def else b.badge }}\n    </div>\n    {% endfor %}\n  </div>\n</section>\n{% endif %}\n\n{% if done_tasks %}\n<section>\n  <h2>Recently completed</h2>\n  <div class="task-list">\n    {% for t in done_tasks %}\n    <div class="card task done-task">\n      <div class="task-main">\n        <div class="task-title">{{ t.title }}</div>\n        <div class="task-meta">\n          <span>Finished {{ t.completed_at|localdt }}</span>\n          {% if t.postpones %}<span class="tag tag-postpone">postponed ×{{ t.postpones }}</span>{% endif %}\n          <span class="tag tag-points">+{{ t.points_awarded }} pts</span>\n        </div>\n      </div>\n    </div>\n    {% endfor %}\n  </div>\n</section>\n{% endif %}\n{% endblock %}\n',
    'login.html': '{% extends "base.html" %}\n{% block title %}Log in · QuestLog{% endblock %}\n{% block content %}\n<div class="card auth-card">\n  <h1>Log in</h1>\n  <form method="post" action="{{ url_for(\'login\') }}">\n    <label>Username <input type="text" name="username" required autocomplete="username"></label>\n    <label>Password <input type="password" name="password" required autocomplete="current-password"></label>\n    <button class="btn btn-primary btn-block" type="submit">Log in</button>\n  </form>\n  <p class="hint">No account yet? <a href="{{ url_for(\'register\') }}">Sign up</a></p>\n</div>\n{% endblock %}\n',
    'register.html': '{% extends "base.html" %}\n{% block title %}Sign up · QuestLog{% endblock %}\n{% block content %}\n<div class="card auth-card">\n  <h1>Create your account</h1>\n  <form method="post" action="{{ url_for(\'register\') }}">\n    <label>Username <input type="text" name="username" required minlength="3" maxlength="20" autocomplete="username"></label>\n    <label>Password <input type="password" name="password" required minlength="8" autocomplete="new-password"></label>\n    <label>Repeat password <input type="password" name="confirm" required minlength="8" autocomplete="new-password"></label>\n    <button class="btn btn-primary btn-block" type="submit">Start questing</button>\n  </form>\n  <p class="hint">Already registered? <a href="{{ url_for(\'login\') }}">Log in</a></p>\n</div>\n{% endblock %}\n',
}

STATIC_CSS = ':root {\n  --bg: #0f1220;\n  --card: #1a1f33;\n  --card-border: #2a3152;\n  --text: #e8eaf6;\n  --muted: #9aa3c0;\n  --primary: #7c5cff;\n  --primary-hover: #6a4ae8;\n  --warn: #f0a13c;\n  --danger: #e5534b;\n  --success: #3fb27f;\n  --info: #4aa8e0;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  font-family: "Segoe UI", system-ui, -apple-system, sans-serif;\n  background: radial-gradient(1200px 600px at 70% -10%, #232a4d 0%, var(--bg) 55%);\n  color: var(--text);\n  min-height: 100vh;\n}\n\n.nav {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 14px 24px;\n  border-bottom: 1px solid var(--card-border);\n  background: rgba(15, 18, 32, 0.8);\n  position: sticky;\n  top: 0;\n  backdrop-filter: blur(6px);\n}\n\n.brand {\n  font-size: 20px;\n  font-weight: 700;\n  color: var(--text);\n  text-decoration: none;\n}\n\n.nav-right { display: flex; align-items: center; gap: 12px; }\n.nav-user { color: var(--muted); font-size: 14px; }\n.inline { display: inline; margin: 0; }\n\n.container { max-width: 900px; margin: 0 auto; padding: 24px 16px 64px; }\n\nh1 { font-size: 22px; margin: 0 0 16px; }\nh2 { font-size: 17px; margin: 28px 0 12px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.06em; }\n\n.card {\n  background: var(--card);\n  border: 1px solid var(--card-border);\n  border-radius: 12px;\n  padding: 18px;\n  margin-bottom: 16px;\n}\n\n.stats {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));\n  gap: 12px;\n  margin-bottom: 8px;\n}\n\n.stat { text-align: center; margin-bottom: 0; }\n.stat-label { font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.06em; }\n.stat-value { font-size: 28px; font-weight: 700; margin: 6px 0; }\n.stat-sub { font-size: 12px; color: var(--muted); }\n\n.progress {\n  height: 10px;\n  background: #0d1020;\n  border-radius: 999px;\n  overflow: hidden;\n  margin: 10px 0 6px;\n}\n.progress-fill {\n  height: 100%;\n  background: linear-gradient(90deg, var(--primary), #b18cff);\n  border-radius: 999px;\n  transition: width 0.3s ease;\n}\n\n.task-form { display: grid; grid-template-columns: 1fr; gap: 10px; }\n.task-form input[type="text"],\n.task-form input[type="datetime-local"],\n.task-form select,\n.task-form textarea,\n.auth-card input {\n  width: 100%;\n  padding: 10px 12px;\n  border-radius: 8px;\n  border: 1px solid var(--card-border);\n  background: #12162a;\n  color: var(--text);\n  font-size: 14px;\n  font-family: inherit;\n}\n.task-form input:focus, .task-form select:focus, .task-form textarea:focus,\n.auth-card input:focus { outline: 2px solid var(--primary); outline-offset: -1px; }\n.task-form textarea { resize: vertical; }\n\n.btn {\n  display: inline-block;\n  border: none;\n  border-radius: 8px;\n  padding: 9px 16px;\n  font-size: 14px;\n  font-weight: 600;\n  cursor: pointer;\n  text-decoration: none;\n  color: var(--text);\n  background: #2a3152;\n}\n.btn-primary { background: var(--primary); color: #fff; }\n.btn-primary:hover { background: var(--primary-hover); }\n.btn-warn { background: transparent; color: var(--warn); border: 1px solid var(--warn); }\n.btn-warn:hover { background: rgba(240, 161, 60, 0.12); }\n.btn-ghost { background: transparent; color: var(--muted); border: 1px solid var(--card-border); }\n.btn-ghost:hover { color: var(--text); }\n.btn-block { width: 100%; margin-top: 6px; }\n\n.hint { font-size: 12px; color: var(--muted); margin: 10px 0 0; }\n.hint a { color: #b18cff; }\n\n.task { display: flex; justify-content: space-between; gap: 14px; align-items: flex-start; }\n.task.overdue { border-color: rgba(229, 83, 75, 0.5); }\n.task-main { flex: 1; min-width: 0; }\n.task-title { font-weight: 600; font-size: 15px; word-break: break-word; }\n.task-desc { color: var(--muted); font-size: 13px; margin-top: 4px; white-space: pre-wrap; }\n.task-meta { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-top: 8px; font-size: 12px; color: var(--muted); }\n.task-actions { display: flex; gap: 8px; flex-shrink: 0; }\n.task-actions form { margin: 0; }\n\n.done-task { opacity: 0.75; }\n.done-task .task-title { text-decoration: line-through; }\n\n.tag {\n  padding: 2px 8px;\n  border-radius: 999px;\n  background: #12162a;\n  border: 1px solid var(--card-border);\n  font-size: 11px;\n}\n.tag-easy { color: #6fd3a7; }\n.tag-normal { color: #8ab4ff; }\n.tag-hard { color: #ff8a80; }\n.tag-postpone { color: var(--warn); }\n.tag-points { color: #b18cff; }\n\n.badge-list { display: flex; flex-wrap: wrap; gap: 10px; }\n.badge {\n  background: var(--card);\n  border: 1px solid var(--card-border);\n  border-radius: 999px;\n  padding: 8px 14px;\n  font-size: 13px;\n}\n\n.empty { color: var(--muted); }\n\n.flashes { margin-bottom: 16px; display: grid; gap: 8px; }\n.flash {\n  padding: 10px 14px;\n  border-radius: 8px;\n  font-size: 14px;\n  border: 1px solid;\n}\n.flash-success { background: rgba(63, 178, 127, 0.12); border-color: var(--success); color: #7fe0b2; }\n.flash-error { background: rgba(229, 83, 75, 0.12); border-color: var(--danger); color: #ff9d97; }\n.flash-info { background: rgba(74, 168, 224, 0.12); border-color: var(--info); color: #9fd4f5; }\n.flash-badge { background: rgba(124, 92, 255, 0.15); border-color: var(--primary); color: #c9b8ff; }\n\n.auth-card { max-width: 380px; margin: 48px auto; }\n.auth-card label { display: block; font-size: 13px; color: var(--muted); margin-bottom: 12px; }\n.auth-card input { margin-top: 6px; }\n'
